package ca.yorku.eecs3311.coursepilot.cli;
import ca.yorku.eecs3311.coursepilot.application.service.ProgressService; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import org.springframework.stereotype.Component; import picocli.CommandLine.*;
@Component @Command(name="progress",description="Show deterministic course progress",mixinStandardHelpOptions=true) public class ProgressCommand implements Runnable {private final ProgressService progress;private final StudyAgentFacade facade;public ProgressCommand(ProgressService p,StudyAgentFacade f){progress=p;facade=f;}@Option(names="--course",required=true)String course;public void run(){var c=facade.getCourseByCode(course);var p=progress.summarize(c.id());System.out.printf("%s: %.1f%% %s (%d activities)%n",c.courseCode(),p.overallScore(),p.overallStatus(),p.activityCount());p.topics().forEach(t->System.out.printf("- %s: %.1f%% %s%n",t.topic(),t.score(),t.status()));}}
